// Project Euler 98: largest square number formed by an anagram word pair.
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
public class Problem098 {
    private static final String DATA = "";
    private static String words() throws IOException {
        try (InputStream in = new java.util.zip.GZIPInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(DATA)))) {
            return new Scanner(in, "US-ASCII").useDelimiter("\\A").next();
        }
    }
    private static final Map<Integer, Set<Long>> SQUARES = new HashMap<>();
    private static Set<Long> squares(int length) {
        return SQUARES.computeIfAbsent(length, n -> {
            long low = (long) Math.ceil(Math.sqrt(Math.pow(10, n - 1))), high = (long) Math.floor(Math.sqrt(Math.pow(10, n) - 1));
            Set<Long> result = new HashSet<>(); for (long i = low; i <= high; i++) result.add(i * i); return result;
        });
    }
    private static long mappedSquare(String from, String to, long square, Set<Long> allSquares) {
        int[] letter = new int[26], digit = new int[10]; Arrays.fill(letter, -1); Arrays.fill(digit, -1);
        String text = Long.toString(square);
        for (int i = 0; i < from.length(); i++) {
            int l = from.charAt(i) - 'A', d = text.charAt(i) - '0';
            if (letter[l] != -1 && letter[l] != d || digit[d] != -1 && digit[d] != l) return 0;
            letter[l] = d; digit[d] = l;
        }
        if (letter[to.charAt(0) - 'A'] == 0) return 0;
        long value = 0; for (int i = 0; i < to.length(); i++) value = value * 10 + letter[to.charAt(i) - 'A'];
        return allSquares.contains(value) ? value : 0;
    }
    public static void main(String[] args) throws Exception {
        Map<String, List<String>> groups = new HashMap<>();
        for (String word : words().replace("\"", "").split(",")) { char[] a = word.toCharArray(); Arrays.sort(a); groups.computeIfAbsent(new String(a), k -> new ArrayList<>()).add(word); }
        long answer = 0;
        for (List<String> group : groups.values()) if (group.size() > 1) {
            int length = group.get(0).length(); Set<Long> all = squares(length);
            for (int i = 0; i < group.size(); i++) for (int j = i + 1; j < group.size(); j++)
                for (long square : all) { long other = mappedSquare(group.get(i), group.get(j), square, all); if (other != 0) answer = Math.max(answer, Math.max(square, other)); }
        }
        System.out.println(answer);
    }
}
